CREATE TABLE users(id BIGSERIAL PRIMARY KEY, first_name VARCHAR(80) NOT NULL, last_name VARCHAR(80) NOT NULL, email VARCHAR(254) NOT NULL UNIQUE, password_hash VARCHAR(100) NOT NULL, role VARCHAR(20) NOT NULL CHECK(role IN ('CUSTOMER','ADMIN')), created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE categories(id BIGSERIAL PRIMARY KEY, name VARCHAR(80) NOT NULL UNIQUE, slug VARCHAR(100) NOT NULL UNIQUE);
CREATE TABLE products(id BIGSERIAL PRIMARY KEY, name VARCHAR(120) NOT NULL, slug VARCHAR(150) NOT NULL UNIQUE, short_description VARCHAR(240) NOT NULL, description TEXT NOT NULL, price NUMERIC(12,2) NOT NULL CHECK(price>0), currency VARCHAR(3) NOT NULL DEFAULT 'USD' CHECK(currency='USD'), category_id BIGINT NOT NULL REFERENCES categories(id), origin VARCHAR(100) NOT NULL, roast_level VARCHAR(30) NOT NULL, weight INTEGER NOT NULL CHECK(weight>0), stock INTEGER NOT NULL CHECK(stock>=0), main_image VARCHAR(300) NOT NULL, active BOOLEAN NOT NULL DEFAULT true, featured BOOLEAN NOT NULL DEFAULT false, version BIGINT NOT NULL DEFAULT 0, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE product_images(product_id BIGINT NOT NULL REFERENCES products(id) ON DELETE CASCADE, image_url VARCHAR(300) NOT NULL, position INTEGER NOT NULL, PRIMARY KEY(product_id,position));
CREATE TABLE orders(id BIGSERIAL PRIMARY KEY, reference VARCHAR(50) NOT NULL UNIQUE, customer_id BIGINT NOT NULL REFERENCES users(id), idempotency_key UUID NOT NULL, status VARCHAR(20) NOT NULL CHECK(status IN ('PENDING','CONFIRMED','PROCESSING','SHIPPED','COMPLETED','CANCELLED')), total NUMERIC(12,2) NOT NULL CHECK(total>=0), currency VARCHAR(3) NOT NULL DEFAULT 'USD', recipient VARCHAR(160) NOT NULL, address VARCHAR(300) NOT NULL, city VARCHAR(100) NOT NULL, postal_code VARCHAR(30) NOT NULL, country VARCHAR(100) NOT NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), UNIQUE(customer_id,idempotency_key));
CREATE TABLE order_items(id BIGSERIAL PRIMARY KEY, order_id BIGINT NOT NULL REFERENCES orders(id), product_id BIGINT NOT NULL REFERENCES products(id), name VARCHAR(120) NOT NULL, price NUMERIC(12,2) NOT NULL, quantity INTEGER NOT NULL CHECK(quantity>0));
CREATE TABLE inventory_movements(id BIGSERIAL PRIMARY KEY, product_id BIGINT NOT NULL REFERENCES products(id), delta INTEGER NOT NULL, reason VARCHAR(100) NOT NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE INDEX products_catalog_idx ON products(active,category_id,price); CREATE INDEX orders_customer_idx ON orders(customer_id,created_at); CREATE INDEX orders_status_idx ON orders(status); CREATE INDEX inventory_product_idx ON inventory_movements(product_id,created_at);
CREATE TABLE SPRING_SESSION(PRIMARY_ID CHAR(36) PRIMARY KEY,SESSION_ID CHAR(36) NOT NULL,CREATION_TIME BIGINT NOT NULL,LAST_ACCESS_TIME BIGINT NOT NULL,MAX_INACTIVE_INTERVAL INT NOT NULL,EXPIRY_TIME BIGINT NOT NULL,PRINCIPAL_NAME VARCHAR(100));
CREATE UNIQUE INDEX SPRING_SESSION_IX1 ON SPRING_SESSION(SESSION_ID);CREATE INDEX SPRING_SESSION_IX2 ON SPRING_SESSION(EXPIRY_TIME);CREATE INDEX SPRING_SESSION_IX3 ON SPRING_SESSION(PRINCIPAL_NAME);
CREATE TABLE SPRING_SESSION_ATTRIBUTES(SESSION_PRIMARY_ID CHAR(36) NOT NULL REFERENCES SPRING_SESSION(PRIMARY_ID) ON DELETE CASCADE,ATTRIBUTE_NAME VARCHAR(200) NOT NULL,ATTRIBUTE_BYTES BYTEA NOT NULL,PRIMARY KEY(SESSION_PRIMARY_ID,ATTRIBUTE_NAME));
